M = Mod('m07', 16, dict(fb=('Feedback oscillator conditions', 'Điều kiện của mạch dao động hồi tiếp'), rc=('RC oscillators', 'Mạch dao động RC'), lc=('LC and crystal oscillators', 'Mạch dao động LC và thạch anh'), rx=('Relaxation oscillators', 'Mạch dao động thư giãn'), t555=('The 555 timer', 'IC định thời 555')))
mcq, tf, ca, ess = M.mcq, M.tf, M.ca, M.ess
mcq(1,846,'An oscillator differs from an amplifier because the oscillator','Mạch dao động khác bộ khuếch đại ở chỗ mạch dao động',[('has more gain','có độ lợi lớn hơn'),('requires no input signal','không cần tín hiệu vào'),('requires no dc supply','không cần nguồn một chiều'),('always has the same output','luôn có cùng ngõ ra')],1,'An oscillator generates its own output from dc power; it still needs the supply.','Mạch dao động tự tạo tín hiệu ra từ nguồn một chiều; nó vẫn cần nguồn cấp.','fb')
mcq(2,846,'One condition for oscillation is','Một điều kiện để dao động là',[('a phase shift around the feedback loop of 180°','độ lệch pha vòng hồi tiếp 180°'),('a gain around the feedback loop of one-third','độ lợi vòng hồi tiếp bằng một phần ba'),('a phase shift around the feedback loop of 0°','độ lệch pha vòng hồi tiếp 0°'),('a gain around the feedback loop of less than 1','độ lợi vòng hồi tiếp nhỏ hơn 1')],2,'Positive feedback needs a net phase shift of 0° (or 360°) around the loop.','Hồi tiếp dương cần độ lệch pha tổng bằng 0° (hoặc 360°) quanh vòng.','fb')
mcq(3,846,'A second condition for oscillation is','Điều kiện thứ hai để dao động là',[('no gain around the feedback loop','không có độ lợi quanh vòng hồi tiếp'),('a gain of 1 around the feedback loop','độ lợi quanh vòng hồi tiếp bằng 1'),('the attenuation of the feedback circuit must be one-third','độ suy giảm của mạch hồi tiếp phải bằng một phần ba'),('the feedback circuit must be capacitive','mạch hồi tiếp phải mang tính dung kháng')],1,'The loop gain Av·B must equal 1 to sustain oscillation (one-third is specific to the Wien bridge).','Độ lợi vòng Av·B phải bằng 1 để duy trì dao động (một phần ba chỉ riêng cho cầu Wien).','fb')
mcq(4,846,'In a certain oscillator, Av = 50. The attenuation of the feedback circuit must be','Trong một mạch dao động có Av = 50, độ suy giảm của mạch hồi tiếp phải bằng',['1','0.01','10','0.02'],3,'Av·B = 1 → B = 1/50 = 0.02.','Av·B = 1 → B = 1/50 = 0,02.','fb')
mcq(5,846,'For an oscillator to properly start, the gain around the feedback loop must initially be','Để mạch dao động khởi động đúng, độ lợi quanh vòng hồi tiếp ban đầu phải',[('1','1'),('less than 1','nhỏ hơn 1'),('greater than 1','lớn hơn 1'),('equal to B','bằng B')],2,'Loop gain > 1 lets the oscillation grow from noise before it settles at 1.','Độ lợi vòng > 1 cho phép dao động lớn dần từ nhiễu rồi ổn định ở 1.','fb')
mcq(6,846,'Wien-bridge oscillators are based on','Mạch dao động cầu Wien dựa trên',[('positive feedback','hồi tiếp dương'),('negative feedback','hồi tiếp âm'),('the piezoelectric effect','hiệu ứng áp điện'),('high gain','độ lợi cao')],0,'The lead-lag network provides the positive feedback (with negative feedback only for gain control).','Mạng sớm–trễ tạo hồi tiếp dương (hồi tiếp âm chỉ để điều chỉnh độ lợi).','rc')
mcq(7,846,'In a Wien-bridge oscillator, if the resistances in the positive feedback circuit are decreased, the frequency','Ở mạch cầu Wien, nếu giảm các điện trở trong mạch hồi tiếp dương thì tần số',[('decreases','giảm'),('increases','tăng'),('remains the same','không đổi')],1,'fr = 1/(2πRC): smaller R gives a higher frequency.','fr = 1/(2πRC): R nhỏ hơn cho tần số cao hơn.','rc')
mcq(8,846,'The Wien-bridge oscillator’s positive feedback circuit is','Mạch hồi tiếp dương của dao động cầu Wien là',[('an RL circuit','mạch RL'),('an LC circuit','mạch LC'),('a voltage divider','bộ chia áp'),('a lead-lag circuit','mạch sớm–trễ')],3,'A lead-lag RC network (attenuation 1/3 at fr, 0° phase).','Mạng RC sớm–trễ (suy giảm 1/3 tại fr, pha 0°).','rc')
mcq(9,846,'A phase-shift oscillator has','Mạch dao động dịch pha có',[('three RC circuits','ba mạch RC'),('three LC circuits','ba mạch LC'),('a T-type circuit','một mạch kiểu T'),('a π-type circuit','một mạch kiểu π')],0,'Three RC sections give 3 × 60° = 180°, which the inverting amplifier completes to 360°.','Ba khâu RC cho 3 × 60° = 180°, mạch khuếch đại đảo bổ sung thành 360°.','rc')
mcq(10,846,'Colpitts, Clapp, and Hartley are names that refer to','Colpitts, Clapp và Hartley là tên chỉ',[('types of RC oscillators','các loại mạch dao động RC'),('inventors of the transistor','những người phát minh transistor'),('types of LC oscillators','các loại mạch dao động LC'),('types of filters','các loại bộ lọc')],2,'All three use LC resonant tanks.','Cả ba đều dùng mạch cộng hưởng LC.','lc')
mcq(11,846,'The main feature of a crystal oscillator is','Đặc điểm chính của dao động thạch anh là',[('economy','tính kinh tế'),('reliability','độ tin cậy'),('stability','độ ổn định'),('high frequency','tần số cao')],2,'The quartz crystal gives a very stable frequency.','Tinh thể thạch anh cho tần số rất ổn định.','lc')
mcq(12,846,'An oscillator whose frequency is changed by a variable dc voltage is known as','Mạch dao động có tần số thay đổi theo điện áp một chiều biến đổi gọi là',[('a crystal oscillator','dao động thạch anh'),('a VCO','VCO'),('an Armstrong oscillator','dao động Armstrong'),('a piezoelectric device','linh kiện áp điện')],1,'VCO = voltage-controlled oscillator.','VCO = voltage-controlled oscillator (dao động điều khiển bằng điện áp).','rx')
mcq(13,846,'The operation of a relaxation oscillator is based on','Hoạt động của mạch dao động thư giãn dựa trên',[('the charging and discharging of a capacitor','sự nạp và xả của tụ điện'),('a highly selective resonant circuit','mạch cộng hưởng có tính chọn lọc cao'),('a very stable supply voltage','điện áp nguồn rất ổn định'),('low power consumption','công suất tiêu thụ thấp')],0,'The capacitor charges and discharges between two thresholds.','Tụ nạp và xả giữa hai ngưỡng.','rx')
mcq(14,847,'Which one of the following is not an input or output of the 555 timer?','Chân nào sau đây không phải ngõ vào hay ngõ ra của IC 555?',[('Threshold','Threshold'),('Control voltage','Control voltage'),('Clock','Clock'),('Trigger','Trigger'),('Discharge','Discharge'),('Reset','Reset')],2,'The 555 pins are Threshold, Control, Trigger, Discharge, Reset, Output, VCC and GND; it has no clock pin.','Các chân 555 gồm Threshold, Control, Trigger, Discharge, Reset, Output, VCC và GND; không có chân clock.','t555')
TF = [(1,'Two categories of oscillators are feedback and relaxation.','Hai loại mạch dao động là hồi tiếp và thư giãn.',1,'Sinusoidal feedback oscillators and nonsinusoidal relaxation oscillators.','Dao động hồi tiếp (sin) và dao động thư giãn (không sin).','fb'),
 (2,'A feedback oscillator uses only negative feedback.','Mạch dao động hồi tiếp chỉ dùng hồi tiếp âm.',0,'It uses positive feedback.','Nó dùng hồi tiếp dương.','fb'),
 (3,'Positive feedback is never used in an oscillator.','Hồi tiếp dương không bao giờ được dùng trong mạch dao động.',0,'It is essential to oscillation.','Nó là yếu tố thiết yếu của dao động.','fb'),
 (4,'The net phase shift around the oscillator feedback loop must be zero.','Độ lệch pha tổng quanh vòng hồi tiếp của mạch dao động phải bằng không.',1,'0° (or 360°).','0° (hoặc 360°).','fb'),
 (5,'The voltage gain around the closed feedback loop must be greater than 1 to sustain oscillations.','Độ lợi điện áp quanh vòng hồi tiếp kín phải lớn hơn 1 để duy trì dao động.',0,'It must equal 1 to sustain; it must exceed 1 only for start-up.','Phải bằng 1 để duy trì; chỉ phải lớn hơn 1 lúc khởi động.','fb'),
 (6,'For start-up, the loop gain must be greater than 1.','Khi khởi động, độ lợi vòng phải lớn hơn 1.',1,'So the oscillation grows from noise.','Để dao động lớn dần từ nhiễu.','fb'),
 (7,'A Wien-bridge oscillator uses an RC circuit in the positive feedback loop.','Mạch dao động cầu Wien dùng một mạch RC trong vòng hồi tiếp dương.',1,'The lead-lag RC network.','Mạng RC sớm–trễ.','rc'),
 (8,'The phase-shift oscillator utilizes RC circuits.','Mạch dao động dịch pha dùng các mạch RC.',1,'Three RC sections.','Ba khâu RC.','rc'),
 (9,'The twin-T oscillator contains an LC feedback circuit.','Mạch dao động twin-T có mạch hồi tiếp LC.',0,'Twin-T is an RC network.','Twin-T là mạng RC.','rc'),
 (10,'Colpitts, Clapp, Hartley, and Armstrong are examples of LC oscillators.','Colpitts, Clapp, Hartley và Armstrong là các ví dụ về mạch dao động LC.',1,'All use LC tanks.','Tất cả dùng mạch cộng hưởng LC.','lc'),
 (11,'The crystal oscillator is based on the photoelectric effect.','Mạch dao động thạch anh dựa trên hiệu ứng quang điện.',0,'It is based on the piezoelectric effect.','Nó dựa trên hiệu ứng áp điện.','lc'),
 (12,'A relaxation oscillator uses no positive feedback.','Mạch dao động thư giãn không dùng hồi tiếp dương.',0,'Floyd’s relaxation oscillators use a comparator with positive feedback (regenerative switching).','Các dao động thư giãn trong Floyd dùng mạch so sánh có hồi tiếp dương (chuyển trạng thái tái sinh).','rx'),
 (13,'Most relaxation oscillators produce sinusoidal outputs.','Phần lớn mạch dao động thư giãn cho ngõ ra hình sin.',0,'They produce square, triangular or sawtooth waves.','Chúng tạo sóng vuông, tam giác hoặc răng cưa.','rx'),
 (14,'VCO stands for variable-capacitance oscillator.','VCO là viết tắt của “variable-capacitance oscillator”.',0,'It stands for voltage-controlled oscillator.','Nó là “voltage-controlled oscillator”.','rx'),
 (15,'The 555 timer can be used as an oscillator.','IC định thời 555 có thể dùng làm mạch dao động.',1,'The astable configuration.','Cấu hình phi ổn (astable).','t555')]
for n, en, vi, v, xe, xv, tp in TF: tf(n, 845, en, vi, v, xe, xv, tp)
F = 'assets/figs/m07/'
ca(1,845,'If R1 and R2 are increased to 18 kΩ in Figure 16–12, the frequency of oscillation will','Nếu tăng R1 và R2 lên 18 kΩ trong Hình 16–12 thì tần số dao động sẽ',F+'fig16_12.png',1,'fr = 1/(2πRC) falls as R rises (10 kΩ → 18 kΩ).','fr = 1/(2πRC) giảm khi R tăng (10 kΩ → 18 kΩ).','rc')
ca(2,845,'If the feedback potentiometer Rf is adjusted to a higher value, the voltage gain in Figure 16–12 will','Nếu chỉnh biến trở hồi tiếp Rf lên giá trị cao hơn thì độ lợi điện áp ở Hình 16–12 sẽ',F+'fig16_12.png',0,'The amplifier gain is 1 + Rf/ri(JFET): it rises with Rf.','Độ lợi mạch khuếch đại là 1 + Rf/ri(JFET): tăng theo Rf.','rc')
ca(3,845,'In Figure 16–14, if the Rf is decreased, the feedback attenuation will','Ở Hình 16–14, nếu giảm Rf thì độ suy giảm của mạch hồi tiếp sẽ',F+'fig16_14.png',2,'The attenuation (1/29 at fr) is set by the three RC sections; Rf sets only the amplifier gain.','Độ suy giảm (1/29 tại fr) do ba khâu RC quyết định; Rf chỉ đặt độ lợi mạch khuếch đại.','rc')
ca(4,845,'If the capacitors in Figure 16–14 are increased to 0.01 μF, the frequency of oscillation will','Nếu tăng các tụ ở Hình 16–14 lên 0,01 μF thì tần số dao động sẽ',F+'fig16_14.png',1,'fr = 1/(2π√6·RC) falls ten-fold when C rises ten-fold.','fr = 1/(2π√6·RC) giảm mười lần khi C tăng mười lần.','rc')
ca(5,845,'In order to increase VUTP in Figure 16–30, R3 must','Để tăng VUTP ở Hình 16–30 thì R3 phải',F+'fig16_30.png',0,'VUTP = (R3/R2)(+Vmax): increasing R3 raises the upper trigger point.','VUTP = (R3/R2)(+Vmax): tăng R3 làm ngưỡng trên cao hơn.','rx')
ca(7,846,'If the value of R1 in Figure 16–32 is decreased, the peak value of the sawtooth output will','Nếu giảm giá trị R1 ở Hình 16–32 thì giá trị đỉnh của sóng răng cưa sẽ',F+'fig16_32.png',2,'The peak is clamped by the diode and the R3/R4 divider; R1 only changes the input level and so the ramp slope (frequency).','Đỉnh bị điốt và bộ chia R3/R4 kẹp; R1 chỉ đổi mức vào, tức độ dốc (tần số).','rx')
ca(8,846,'If the diode in Figure 16–40 opens, the duty cycle will','Nếu điốt ở Hình 16–40 bị hở thì chu kỳ làm việc sẽ',F+'fig16_40.png',0,'Without D1 the capacitor charges through R1 + R2: duty cycle (R1+R2)/(R1+2R2) is larger than with the bypass diode (≈ R1/(R1+R2)).','Không có D1 tụ nạp qua R1 + R2: chu kỳ (R1+R2)/(R1+2R2) lớn hơn khi có điốt rẽ (≈ R1/(R1+R2)).','t555')
f6 = 1 / (2 * math.pi * 6.2e3 * 0.02e-6); f11 = 1 / (2 * math.pi * math.sqrt(6) * 4.7e3 * 0.022e-6); f20 = 1.44 / ((1e3 + 2 * 3.3e3) * 0.047e-6); c21 = 1.44 / ((1e3 + 2 * 3.3e3) * 25e3); v18 = 3 / (4.7e3 * 1e-9) * 10e-6
ess(3,847,'The amplifier of an oscillator has a voltage gain of 75. What attenuation must the feedback circuit have to sustain oscillation?','Mạch khuếch đại của một mạch dao động có độ lợi 75. Mạch hồi tiếp phải có độ suy giảm bao nhiêu để duy trì dao động?',f'Av·B = 1 → B = 1/75 = {1/75:.4f} (book: 0.0133).',f'Av·B = 1 → B = 1/75 = {1/75:.4f} (sách: 0,0133).','fb',1,True)
ess(5,847,'A lead-lag circuit has a resonant frequency of 3.5 kHz. An input of 2.2 V rms at fr is applied. What is the rms output?','Mạch sớm–trễ có tần số cộng hưởng 3,5 kHz. Đặt tín hiệu vào 2,2 V rms tại fr. Điện áp ra rms là bao nhiêu?',f'At fr the attenuation is 1/3: Vout = 2.2/3 = {2.2/3*1e3:.0f} mV (book: 733 mV).',f'Tại fr độ suy giảm là 1/3: Vout = 2,2/3 = {2.2/3*1e3:.0f} mV (sách: 733 mV).','rc',1,True)
ess(6,847,'Resonant frequency of a lead-lag circuit with R1 = R2 = 6.2 kΩ and C1 = C2 = 0.02 μF.','Tần số cộng hưởng của mạch sớm–trễ có R1 = R2 = 6,2 kΩ và C1 = C2 = 0,02 μF.',f'fr = 1/(2πRC) = 1/(2π × 6.2 kΩ × 0.02 μF) = {f6:.0f} Hz.',f'fr = 1/(2πRC) = 1/(2π × 6,2 kΩ × 0,02 μF) = {f6:.0f} Hz.','rc')
ess(7,847,'Figure 16–57 (R1 = 100 kΩ): find R2 so the circuit oscillates. The total gain must be 3 when the zeners conduct.','Hình 16–57 (R1 = 100 kΩ): tìm R2 để mạch dao động. Độ lợi tổng phải bằng 3 khi các zener dẫn.','Noninverting gain 1 + R1/R2 = 3 → R1/R2 = 2 → R2 = 100 kΩ/2 = 50 kΩ (book: 50 kΩ).','Độ lợi không đảo 1 + R1/R2 = 3 → R1/R2 = 2 → R2 = 100 kΩ/2 = 50 kΩ (sách: 50 kΩ).','rc',2,True)
ess(11,848,'Phase-shift oscillator of Fig. 16–59 (Ri = R = 4.7 kΩ, C = 0.022 μF): find Rf and fr.','Mạch dao động dịch pha Hình 16–59 (Ri = R = 4,7 kΩ, C = 0,022 μF): tìm Rf và fr.',f'Rf = 29·Ri = 29 × 4.7 kΩ = {29*4.7:.1f} kΩ ≈ 136 kΩ; fr = 1/(2π√6·RC) = {f11:.0f} Hz (book: 136 kΩ, 628 Hz).',f'Rf = 29·Ri = 29 × 4,7 kΩ = {29*4.7:.1f} kΩ ≈ 136 kΩ; fr = 1/(2π√6·RC) = {f11:.0f} Hz (sách: 136 kΩ, 628 Hz).','rc',2,True)
ess(13,848,'Colpitts oscillator of Fig. 16–61 with C1 = 470 pF and C2 = 47 pF: gain the amplifier stage must have for sustained oscillation.','Mạch Colpitts Hình 16–61 với C1 = 470 pF và C2 = 47 pF: độ lợi của tầng khuếch đại để duy trì dao động.','Av = C1/C2 = 470 pF / 47 pF = 10 (book: 10).','Av = C1/C2 = 470 pF / 47 pF = 10 (sách: 10).','lc',2,True)
ess(18,849,'A sawtooth generator has VIN = 3 V, R = 4.7 kΩ, C = 0.001 μF. Peak-to-peak output for a period of 10 μs?','Bộ phát răng cưa có VIN = 3 V, R = 4,7 kΩ, C = 0,001 μF. Điện áp ra đỉnh–đỉnh khi chu kỳ 10 μs là bao nhiêu?',f'Ramp rate = VIN/(RC) = 3/(4.7 kΩ × 0.001 μF) = {3/(4.7e3*1e-9)/1e6:.3f} V/μs; Vpp = rate × T = {v18:.2f} V.',f'Tốc độ dốc = VIN/(RC) = 3/(4,7 kΩ × 0,001 μF) = {3/(4.7e3*1e-9)/1e6:.3f} V/μs; Vpp = tốc độ × T = {v18:.2f} V.','rx')
ess(19,850,'Comparator reference voltages inside a 555 timer when VCC = 10 V?','Các điện áp tham chiếu của bộ so sánh trong IC 555 khi VCC = 10 V là bao nhiêu?','Upper comparator (threshold): 2/3 VCC = 6.67 V; lower comparator (trigger): 1/3 VCC = 3.33 V (book: 3.33 V and 6.67 V).','Bộ so sánh trên (threshold): 2/3 VCC = 6,67 V; bộ so sánh dưới (trigger): 1/3 VCC = 3,33 V (sách: 3,33 V và 6,67 V).','t555',1,True)
ess(20,850,'Frequency of the 555 astable oscillator of Fig. 16–64 (R1 = 1.0 kΩ, R2 = 3.3 kΩ, Cext = 0.047 μF).','Tần số của mạch dao động phi ổn 555 ở Hình 16–64 (R1 = 1,0 kΩ, R2 = 3,3 kΩ, Cext = 0,047 μF).',f'f = 1.44/((R1 + 2R2)·Cext) = 1.44/(7.6 kΩ × 0.047 μF) = {f20:.0f} Hz ≈ {f20/1e3:.2f} kHz.',f'f = 1,44/((R1 + 2R2)·Cext) = 1,44/(7,6 kΩ × 0,047 μF) = {f20:.0f} Hz ≈ {f20/1e3:.2f} kHz.','t555')
ess(21,850,'To what value must Cext be changed in Fig. 16–64 to get 25 kHz?','Phải đổi Cext ở Hình 16–64 thành bao nhiêu để được 25 kHz?',f'Cext = 1.44/((R1 + 2R2)·f) = 1.44/(7.6 kΩ × 25 kHz) = {c21*1e6:.4f} μF ≈ 0.0076 μF (book: 0.0076 μF).',f'Cext = 1,44/((R1 + 2R2)·f) = 1,44/(7,6 kΩ × 25 kHz) = {c21*1e6:.4f} μF ≈ 0,0076 μF (sách: 0,0076 μF).','t555',2,True)
ess(22,850,'In an astable 555 with R1 = 3.3 kΩ, what R2 gives a duty cycle of 75 %?','Ở mạch 555 phi ổn có R1 = 3,3 kΩ, R2 bằng bao nhiêu để chu kỳ làm việc là 75 %?','Duty cycle = (R1+R2)/(R1+2R2) = 0.75 → R1 + R2 = 0.75R1 + 1.5R2 → 0.25R1 = 0.5R2 → R2 = R1/2 = 1.65 kΩ (check: (3.3+1.65)/(3.3+3.3) = 0.75).','Chu kỳ làm việc = (R1+R2)/(R1+2R2) = 0,75 → R1 + R2 = 0,75R1 + 1,5R2 → 0,25R1 = 0,5R2 → R2 = R1/2 = 1,65 kΩ (kiểm tra: (3,3+1,65)/(3,3+3,3) = 0,75).','t555',2)
